From 7155b958487236da397c7e16e53966132a647dab Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 23:57:24 +0100
Subject: [PATCH] shell: ignore stray mouse events on a panel hidden by
 auto-hide

At the end of a drag Qt sends a button release with no window to the
top-level window under the cursor, even if KWin is hiding it, so hidden
panels showed tooltips. Ignore those until real input reveals the panel.

BUG: 514219
---
 shell/autohidescreenedge.cpp |  6 ++++++
 shell/autohidescreenedge.h   |  1 +
 shell/panelview.cpp          | 23 +++++++++++++++++++++++
 shell/panelview.h            |  2 ++
 4 files changed, 32 insertions(+)

diff --git a/shell/autohidescreenedge.cpp b/shell/autohidescreenedge.cpp
index db4b1b4c73..d00cba5bdd 100644
--- a/shell/autohidescreenedge.cpp
+++ b/shell/autohidescreenedge.cpp
@@ -65,6 +65,7 @@ public:

     void deactivate() override;
     void activate() override;
+    bool isActive() const override;

 protected:
     bool eventFilter(QObject *watched, QEvent *event) override;
@@ -137,6 +138,11 @@ void WaylandAutoHideScreenEdge::activate()
     }
 }

+bool WaylandAutoHideScreenEdge::isActive() const
+{
+    return m_active && m_edge;
+}
+
 bool WaylandAutoHideScreenEdge::create()
 {
     auto waylandWindow = m_view->nativeInterface<QNativeInterface::Private::QWaylandWindow>();
diff --git a/shell/autohidescreenedge.h b/shell/autohidescreenedge.h
index b4d2423b42..b9de65fd26 100644
--- a/shell/autohidescreenedge.h
+++ b/shell/autohidescreenedge.h
@@ -20,6 +20,7 @@ public:

     virtual void activate() = 0;
     virtual void deactivate() = 0;
+    virtual bool isActive() const = 0;

 protected:
     AutoHideScreenEdge(PanelView *view);
diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..502b681422 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -986,6 +986,7 @@ void PanelView::setAutoHideEnabled(bool enabled)
             m_autoHideScreenEdge = AutoHideScreenEdge::create(this);
         }
         if (enabled) {
+            m_autoHideRevealed = false;
             m_autoHideScreenEdge->activate();
         } else {
             m_autoHideScreenEdge->deactivate();
@@ -1175,6 +1176,7 @@ bool PanelView::event(QEvent *e)
         break;
     case QEvent::Enter:
         m_containsMouse = true;
+        m_autoHideRevealed = true;
         if (edgeActivated()) {
             m_unhideTimer.stop();
         }
@@ -1197,6 +1199,13 @@ bool PanelView::event(QEvent *e)
     case QEvent::MouseButtonDblClick: {
         auto *me = static_cast<QMouseEvent *>(e);

+        // At the end of a drag QtWayland synthesizes a button release without a window, which Qt then sends,
+        // with a move to its position, to the top-level window under the cursor, even if KWin is hiding it.
+        if (isHiddenByAutoHide() && !mouseGrabberItem()) {
+            e->accept();
+            return true;
+        }
+
         // first, don't mess with position if the cursor is actually outside the view:
         // somebody is doing a click and drag that must not break when the cursor i outside
         // BUG 482580: use QRectF for HiDPI
@@ -1245,8 +1254,16 @@ bool PanelView::event(QEvent *e)
         break;
     }

+    case QEvent::TabletPress:
+    case QEvent::TabletMove:
+    case QEvent::TabletRelease:
+    case QEvent::TouchBegin:
+        m_autoHideRevealed = true;
+        break;
+
     case QEvent::DragEnter: {
         m_containsDrag = true;
+        m_autoHideRevealed = true;
         if (edgeActivated()) {
             m_unhideTimer.stop();
         }
@@ -1657,6 +1674,12 @@ bool PanelView::edgeActivated() const
     return m_visibilityMode == PanelView::AutoHide || m_visibilityMode == PanelView::DodgeWindows;
 }

+bool PanelView::isHiddenByAutoHide() const
+{
+    // KWin reveals the panel when the screen edge is triggered without telling us, but then input reaches it
+    return m_autoHideScreenEdge && m_autoHideScreenEdge->isActive() && !m_autoHideRevealed;
+}
+
 void PanelView::updateEnabledBorders()
 {
     if (!rootObject()) {
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..292987dd2e 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -323,6 +323,7 @@ private:
     bool containmentContainsPosition(const QPointF &point) const;
     QPointF positionAdjustedForContainment(const QPointF &point) const;
     bool edgeActivated() const;
+    bool isHiddenByAutoHide() const;
     void positionConfigView();

     int m_offset;
@@ -350,6 +351,7 @@ private:
     bool m_containsDrag = false;
     bool m_fakeEventPending = false;
     bool m_touchingWindow = false;
+    bool m_autoHideRevealed = false;
     Qt::Alignment m_alignment;
     QPointer<PlasmaQuick::ConfigView> m_appletConfigView;
     QPointer<PlasmaQuick::PopupPlasmaWindow> m_panelConfigView;
